944	func jsonArrayExpr(d DialectName, field Field) string {
945		column := qualifyColumn(d, field.Column)
946		switch d {
947		case DialectSQLite, DialectMySQL:
948			return fmt.Sprintf("JSON_EXTRACT(%s, '%s')", column, jsonPath(field))
949		case DialectPostgres:
950			return buildPostgresJSONAccessor(column, field.JSONPath, false)
951		default:
952			return ""
953		}
954	}
