39		})
40		if err != nil {
41			return nil, nil, nil, errors.Wrap(err, "failed to list reactions")
42		}
43		attachments, err := s.Store.ListAttachments(ctx, &store.FindAttachment{
44			MemoID: &memo.ID,
45		})
46		if err != nil {
47			return nil, nil, nil, errors.Wrap(err, "failed to list attachments")
48		}
49		relations, err := s.loadMemoRelations(ctx, memo)
50		if err != nil {
51			return nil, nil, nil, errors.Wrap(err, "failed to load memo relations")
